function gcdImpl(a, b) {
  while (b !== 0) [a, b] = [b, a % b];
  return a;
}

function lcmImpl(a, b) {
  return (a / gcdImpl(a, b)) * b;
}

function gcdArrayImpl(nums) {
  return nums.reduce((g, n) => gcdImpl(g, n));
}

