function sieveImpl(n) {
  const isPrime = new Array(n+1).fill(true);
  isPrime[0] = isPrime[1] = false;
  for (let p=2; p*p<=n; p++) {
    if (isPrime[p]) {
      for (let m=p*p; m<=n; m+=p) isPrime[m] = false;
    }
  }
  return isPrime;
}

function countPrimesImpl(n) {
  if (n < 2) return 0;
  const isPrime = sieveImpl(n-1);
  return isPrime.slice(2).filter(Boolean).length;
}

