function myPowImpl(x, n) {
  if (n < 0) { x = 1 / x; n = -n; }
  let result = 1;
  while (n > 0) {
    if (n & 1) result *= x;
    x *= x;
    n >>= 1;
  }
  return result;
}

function modPowImpl(x, n, m) {
  let result = 1n;
  x = BigInt(x) % BigInt(m);
  n = BigInt(n);
  const mod = BigInt(m);
  while (n > 0n) {
    if (n & 1n) result = (result * x) % mod;
    x = (x * x) % mod;
    n >>= 1n;
  }
  return Number(result);
}

