function spiralOrderImpl(matrix) {
  const result = [];
  if (!matrix.length) return result;
  let top=0, bottom=matrix.length-1, left=0, right=matrix[0].length-1;
  while (top<=bottom && left<=right) {
    for (let c=left;c<=right;c++) result.push(matrix[top][c]); top++;
    for (let r=top;r<=bottom;r++) result.push(matrix[r][right]); right--;
    if (top<=bottom) { for (let c=right;c>=left;c--) result.push(matrix[bottom][c]); bottom--; }
    if (left<=right) { for (let r=bottom;r>=top;r--) result.push(matrix[r][left]); left++; }
  }
  return result;
}

function generateMatrixImpl(n) {
  const m = Array.from({length:n},()=>new Array(n).fill(0));
  let top=0,bottom=n-1,left=0,right=n-1,num=1;
  while (top<=bottom && left<=right) {
    for (let c=left;c<=right;c++) m[top][c]=num++; top++;
    for (let r=top;r<=bottom;r++) m[r][right]=num++; right--;
    if (top<=bottom) { for (let c=right;c>=left;c--) m[bottom][c]=num++; bottom--; }
    if (left<=right) { for (let r=bottom;r>=top;r--) m[r][left]=num++; left++; }
  }
  return m;
}

