function plusOneImpl(digits) {
  for (let i=digits.length-1; i>=0; i--) {
    if (digits[i]<9) { digits[i]++; return digits; }
    digits[i]=0;
  }
  return [1, ...digits];
}

function isHappyImpl(n) {
  function sumSq(x){let s=0;while(x>0){const d=x%10;s+=d*d;x=Math.floor(x/10);}return s;}
  let slow=n, fast=sumSq(n);
  while(fast!==1 && slow!==fast){slow=sumSq(slow);fast=sumSq(sumSq(fast));}
  return fast===1;
}

